template <class TA, class TB, class TD, class CA, class CB, class CD>
__global__ void ws_kernel(TA a, TB b, TD d, CUTE_GRID_CONSTANT CA const ca,
                          CUTE_GRID_CONSTANT CB const cb,
                          CUTE_GRID_CONSTANT CD const cd, int mt, int nt) {
