void launch_ws(Problem p) {
  using CF = WSConfig;
  using MM = typename CF::MM;
  using Tile = typename CF::T;
  auto a = make_tensor(make_gmem_ptr(p.a), make_layout(make_shape(p.m, p.k),
                                                       make_stride(p.k, _1{})));
  auto b = make_tensor(make_gmem_ptr(p.b), make_layout(make_shape(p.n, p.k),
                                                       make_stride(p.k, _1{})));
  auto d = make_tensor(make_gmem_ptr(p.d), make_layout(make_shape(p.m, p.n),
                                                       make_stride(p.n, _1{})));
  auto cluster_layout = tiled_divide(make_layout(Shape<Int<2>, _1, _1>{}),
                                     make_tile(typename MM::AtomThrID{}));
  using CopyOp = std::conditional_t<2 == 1, SM90_TMA_LOAD, SM100_TMA_2SM_LOAD>;
  auto ca = make_tma_atom_A_sm100(CopyOp{}, a, typename CF::AL{}, Tile{}, MM{},
                                  cluster_layout);
  auto cb = make_tma_atom_B_sm100(CopyOp{}, b, typename CF::BL{}, Tile{}, MM{},
                                  cluster_layout);
  auto cd = make_tma_atom(SM90_TMA_STORE{}, d, LD{}, Shape<_128, _64>{});
  auto ta = ca.get_tma_tensor(shape(a));
  auto tb = cb.get_tma_tensor(shape(b));
  auto td = cd.get_tma_tensor(shape(d));
  auto fn = ws_kernel<decltype(ta), decltype(tb), decltype(td), decltype(ca),
                      decltype(cb), decltype(cd)>;
  static bool configured = false;
  if (!configured) {
    CUDA_OK(cudaFuncSetAttribute(fn,
                                 cudaFuncAttributeMaxDynamicSharedMemorySize,
                                 sizeof(typename CF::Storage)));
    configured = true;
  }
  int mt = p.m / (CF::BM * 2), nt = p.n / CF::BN;
  int clusters = std::min(mt * nt, p.sms / 2);
  if constexpr (2 == 1)
    fn<<<clusters, CF::Threads, sizeof(typename CF::Storage)>>>(ta, tb, td, ca,
                                                                cb, cd, mt, nt);
  else {
    cudaLaunchConfig_t config{};
    config.gridDim = dim3(clusters * 2);
    config.blockDim = dim3(CF::Threads);
    config.dynamicSmemBytes = sizeof(typename CF::Storage);
    config.stream = cudaStreamPerThread;
    cudaLaunchAttribute attr{};
    attr.id = cudaLaunchAttributeClusterDimension;
    attr.val.clusterDim = {2, 1, 1};
    config.attrs = &attr;
    config.numAttrs = 1;
    CUDA_OK(cudaLaunchKernelEx(&config, fn, ta, tb, td, ca, cb, cd, mt, nt));
  }
}
